export default {async fetch(request,env){try{const path=new URL(request.url).pathname;if(path.startsWith('/api/'))return await api(request,env,seed);const asset=assets[path];if(!asset)return new Response('Not found',{status:404});return new Response(Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0)),{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});}catch{return Response.json({error:'Shared storage is temporarily unavailable. Please retry.'},{status:503,headers:{'Cache-Control':'no-store'}});}}};
